29	function isWildcardPattern(name: string): boolean {
30	  return name === '*' || name.includes('*');
31	}
32	
33	/**
34	 * Checks if a tool call matches a wildcard pattern.
35	 * Supports global (*) and composite (server__*, *__tool, *__*) patterns.
36	 */
37	function matchesWildcard(
38	  pattern: string,
39	  toolName: string,
40	  serverName: string | undefined,
41	): boolean {
42	  if (pattern === '*') {
43	    return true;
44	  }
45	
46	  if (pattern.includes('__')) {
47	    return matchesCompositePattern(pattern, toolName, serverName);
48	  }
49	
50	  return toolName === pattern;
51	}
52	
53	/**
54	 * Matches composite patterns like "server__*", "*__tool", or "*__*".
55	 */
56	function matchesCompositePattern(
57	  pattern: string,
58	  toolName: string,
59	  serverName: string | undefined,
60	): boolean {
61	  const parts = pattern.split('__');
62	  if (parts.length !== 2) return false;
63	  const [patternServer, patternTool] = parts;
64	
65	  // 1. Identify the tool's components
66	  const { actualServer, actualTool } = getToolMetadata(toolName, serverName);
67	
68	  // 2. Composite patterns require a server context
69	  if (actualServer === undefined) {
70	    return false;
71	  }
72	
73	  // 3. Robustness: if serverName is provided, toolName MUST be qualified by it.
74	  // This prevents "malicious-server" from spoofing "trusted-server" by naming itself "trusted-server__malicious".
75	  if (serverName !== undefined && !toolName.startsWith(serverName + '__')) {
76	    return false;
77	  }
78	
79	  // 4. Match components
80	  const serverMatch = patternServer === '*' || patternServer === actualServer;
81	  const toolMatch = patternTool === '*' || patternTool === actualTool;
82	
83	  return serverMatch && toolMatch;
84	}
85	
86	/**
87	 * Extracts the server and unqualified tool name from a tool call context.
88	 */
89	function getToolMetadata(toolName: string, serverName: string | undefined) {
90	  const sepIndex = toolName.indexOf('__');
91	  const isQualified = sepIndex !== -1;
92	  return {
93	    actualServer:
94	      serverName ?? (isQualified ? toolName.substring(0, sepIndex) : undefined),
95	    actualTool: isQualified ? toolName.substring(sepIndex + 2) : toolName,
96	  };
97	}
98	
99	function ruleMatches(
100	  rule: PolicyRule | SafetyCheckerRule,
101	  toolCall: FunctionCall,
102	  stringifiedArgs: string | undefined,
103	  serverName: string | undefined,
104	  currentApprovalMode: ApprovalMode,
105	  toolAnnotations?: Record<string, unknown>,
106	): boolean {
107	  // Check if rule applies to current approval mode
108	  if (rule.modes && rule.modes.length > 0) {
109	    if (!rule.modes.includes(currentApprovalMode)) {
110	      return false;
111	    }
112	  }
113	
114	  // Check tool name if specified
115	  if (rule.toolName) {
116	    // Support wildcard patterns: "serverName__*" matches "serverName__anyTool"
117	    if (rule.toolName === '*') {
118	      // Match all tools
119	    } else if (isWildcardPattern(rule.toolName)) {
120	      if (
121	        !toolCall.name ||
122	        !matchesWildcard(rule.toolName, toolCall.name, serverName)
123	      ) {
124	        return false;
125	      }
126	    } else if (toolCall.name !== rule.toolName) {
127	      return false;
128	    }
129	  }
130	
131	  // Check annotations if specified
132	  if (rule.toolAnnotations) {
133	    if (!toolAnnotations) {
134	      return false;
135	    }
136	    for (const [key, value] of Object.entries(rule.toolAnnotations)) {
137	      if (toolAnnotations[key] !== value) {
138	        return false;
139	      }
140	    }
141	  }
142	
143	  // Check args pattern if specified
144	  if (rule.argsPattern) {
145	    // If rule has an args pattern but tool has no args, no match
146	    if (!toolCall.args) {
147	      return false;
148	    }
149	    // Use stable JSON stringification with sorted keys to ensure consistent matching
150	    if (
151	      stringifiedArgs === undefined ||
152	      !rule.argsPattern.test(stringifiedArgs)
153	    ) {
154	      return false;
155	    }
156	  }
157	
158	  return true;
159	}
