86	/**
87	 * Evaluates the outcome of a user confirmation and dispatches
88	 * policy config updates.
89	 */
90	export async function updatePolicy(
91	  tool: AnyDeclarativeTool,
92	  outcome: ToolConfirmationOutcome,
93	  confirmationDetails: SerializableConfirmationDetails | undefined,
94	  deps: { config: Config; messageBus: MessageBus },
95	): Promise<void> {
96	  // Mode Transitions (AUTO_EDIT)
97	  if (isAutoEditTransition(tool, outcome)) {
98	    deps.config.setApprovalMode(ApprovalMode.AUTO_EDIT);
99	    return;
100	  }
101	
102	  // Specialized Tools (MCP)
103	  if (confirmationDetails?.type === 'mcp') {
104	    await handleMcpPolicyUpdate(
105	      tool,
106	      outcome,
107	      confirmationDetails,
108	      deps.messageBus,
109	    );
110	    return;
111	  }
112	
113	  // Generic Fallback (Shell, Info, etc.)
114	  await handleStandardPolicyUpdate(
115	    tool,
116	    outcome,
117	    confirmationDetails,
118	    deps.messageBus,
119	  );
120	}
121	
122	/**
123	 * Returns true if the user's 'Always Allow' selection for a specific tool
124	 * should trigger a session-wide transition to AUTO_EDIT mode.
125	 */
126	function isAutoEditTransition(
127	  tool: AnyDeclarativeTool,
128	  outcome: ToolConfirmationOutcome,
129	): boolean {
130	  // TODO: This is a temporary fix to enable AUTO_EDIT mode for specific
131	  // tools. We should refactor this so that callbacks can be removed from
132	  // tools.
133	  return (
134	    outcome === ToolConfirmationOutcome.ProceedAlways &&
135	    EDIT_TOOL_NAMES.has(tool.name)
136	  );
137	}
138	
139	/**
140	 * Handles policy updates for standard tools (Shell, Info, etc.), including
141	 * session-level and persistent approvals.
142	 */
143	async function handleStandardPolicyUpdate(
144	  tool: AnyDeclarativeTool,
145	  outcome: ToolConfirmationOutcome,
146	  confirmationDetails: SerializableConfirmationDetails | undefined,
147	  messageBus: MessageBus,
148	): Promise<void> {
149	  if (
150	    outcome === ToolConfirmationOutcome.ProceedAlways ||
151	    outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave
152	  ) {
153	    const options: PolicyUpdateOptions = {};
154	
155	    if (confirmationDetails?.type === 'exec') {
156	      options.commandPrefix = confirmationDetails.rootCommands;
157	    }
158	
159	    await messageBus.publish({
160	      type: MessageBusType.UPDATE_POLICY,
161	      toolName: tool.name,
162	      persist: outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave,
163	      ...options,
164	    });
165	  }
166	}
167	
168	/**
169	 * Handles policy updates specifically for MCP tools, including session-level
170	 * and persistent approvals.
171	 */
172	async function handleMcpPolicyUpdate(
173	  tool: AnyDeclarativeTool,
174	  outcome: ToolConfirmationOutcome,
175	  confirmationDetails: Extract<
176	    SerializableConfirmationDetails,
177	    { type: 'mcp' }
178	  >,
179	  messageBus: MessageBus,
180	): Promise<void> {
181	  const isMcpAlways =
182	    outcome === ToolConfirmationOutcome.ProceedAlways ||
183	    outcome === ToolConfirmationOutcome.ProceedAlwaysTool ||
184	    outcome === ToolConfirmationOutcome.ProceedAlwaysServer ||
185	    outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave;
186	
187	  if (!isMcpAlways) {
188	    return;
189	  }
190	
191	  let toolName = tool.name;
192	  const persist = outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave;
193	
194	  // If "Always allow all tools from this server", use the wildcard pattern
195	  if (outcome === ToolConfirmationOutcome.ProceedAlwaysServer) {
196	    toolName = `${confirmationDetails.serverName}__*`;
197	  }
198	
199	  await messageBus.publish({
200	    type: MessageBusType.UPDATE_POLICY,
201	    toolName,
202	    mcpName: confirmationDetails.serverName,
203	    persist,
204	  });
