7	import { randomUUID } from 'node:crypto';
8	import { EventEmitter } from 'node:events';
9	import type { PolicyEngine } from '../policy/policy-engine.js';
10	import { PolicyDecision } from '../policy/types.js';
11	import { MessageBusType, type Message } from './types.js';
12	import { safeJsonStringify } from '../utils/safeJsonStringify.js';
13	import { debugLogger } from '../utils/debugLogger.js';
14	
15	export class MessageBus extends EventEmitter {
16	  constructor(
17	    private readonly policyEngine: PolicyEngine,
18	    private readonly debug = false,
19	  ) {
20	    super();
21	    this.debug = debug;
22	  }
23	
24	  private isValidMessage(message: Message): boolean {
25	    if (!message || !message.type) {
26	      return false;
27	    }
28	
29	    if (
30	      message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST &&
31	      !('correlationId' in message)
32	    ) {
33	      return false;
34	    }
35	
36	    return true;
37	  }
38	
39	  private emitMessage(message: Message): void {
40	    this.emit(message.type, message);
41	  }
42	
43	  async publish(message: Message): Promise<void> {
44	    if (this.debug) {
45	      debugLogger.debug(`[MESSAGE_BUS] publish: ${safeJsonStringify(message)}`);
46	    }
47	    try {
48	      if (!this.isValidMessage(message)) {
49	        throw new Error(
50	          `Invalid message structure: ${safeJsonStringify(message)}`,
51	        );
52	      }
53	
54	      if (message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST) {
55	        const { decision } = await this.policyEngine.check(
56	          message.toolCall,
57	          message.serverName,
58	        );
59	
60	        switch (decision) {
61	          case PolicyDecision.ALLOW:
62	            // Directly emit the response instead of recursive publish
63	            this.emitMessage({
64	              type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
65	              correlationId: message.correlationId,
66	              confirmed: true,
67	            });
68	            break;
69	          case PolicyDecision.DENY:
70	            // Emit both rejection and response messages
71	            this.emitMessage({
72	              type: MessageBusType.TOOL_POLICY_REJECTION,
73	              toolCall: message.toolCall,
74	            });
75	            this.emitMessage({
76	              type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
77	              correlationId: message.correlationId,
78	              confirmed: false,
79	            });
80	            break;
81	          case PolicyDecision.ASK_USER:
82	            // Pass through to UI for user confirmation if any listeners exist.
83	            // If no listeners are registered (e.g., headless/ACP flows),
84	            // immediately request user confirmation to avoid long timeouts.
85	            if (
86	              this.listenerCount(MessageBusType.TOOL_CONFIRMATION_REQUEST) > 0
87	            ) {
88	              this.emitMessage(message);
89	            } else {
90	              this.emitMessage({
91	                type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
92	                correlationId: message.correlationId,
93	                confirmed: false,
94	                requiresUserConfirmation: true,
95	              });
96	            }
97	            break;
98	          default:
99	            throw new Error(`Unknown policy decision: ${decision}`);
100	        }
101	      } else {
102	        // For all other message types, just emit them
103	        this.emitMessage(message);
104	      }
105	    } catch (error) {
106	      this.emit('error', error);
107	    }
108	  }
109	
110	  subscribe<T extends Message>(
111	    type: T['type'],
112	    listener: (message: T) => void,
113	  ): void {
114	    this.on(type, listener);
115	  }
116	
117	  unsubscribe<T extends Message>(
118	    type: T['type'],
119	    listener: (message: T) => void,
120	  ): void {
121	    this.off(type, listener);
122	  }
123	
124	  /**
125	   * Request-response pattern: Publish a message and wait for a correlated response
126	   * This enables synchronous-style communication over the async MessageBus
127	   * The correlation ID is generated internally and added to the request
128	   */
129	  async request<TRequest extends Message, TResponse extends Message>(
130	    request: Omit<TRequest, 'correlationId'>,
131	    responseType: TResponse['type'],
132	    timeoutMs: number = 60000,
133	  ): Promise<TResponse> {
134	    const correlationId = randomUUID();
135	
136	    return new Promise<TResponse>((resolve, reject) => {
137	      const timeoutId = setTimeout(() => {
138	        cleanup();
139	        reject(new Error(`Request timed out waiting for ${responseType}`));
140	      }, timeoutMs);
141	
142	      const cleanup = () => {
143	        clearTimeout(timeoutId);
144	        this.unsubscribe(responseType, responseHandler);
145	      };
146	
147	      const responseHandler = (response: TResponse) => {
148	        // Check if this response matches our request
149	        if (
150	          'correlationId' in response &&
151	          response.correlationId === correlationId
152	        ) {
153	          cleanup();
154	          resolve(response);
155	        }
156	      };
157	
158	      // Subscribe to responses
159	      this.subscribe<TResponse>(responseType, responseHandler);
160	
161	      // Publish the request with correlation ID
162	      // eslint-disable-next-line @typescript-eslint/no-floating-promises, @typescript-eslint/no-unsafe-type-assertion
163	      this.publish({ ...request, correlationId } as TRequest);
164	    });
165	  }
166	}
